const fs = require('node:fs')
const stripTransaction = text => text.replace(/^begin;\s*$/gmi, '').replace(/^commit;\s*$/gmi, '').trim()
const migration = fs.readFileSync('supabase/migrations/20261003120000_property_interests.sql','utf8')
const accounts = fs.readFileSync('supabase/testing/provision-interest-users.sql','utf8')
fs.writeFileSync('supabase/testing/setup-interests.sql',
  '-- Generated by node scripts/build-interest-setup.cjs. Run once in Supabase SQL Editor.\n' +
  '-- Creates/updates interest matching and resets ONLY the two authorized test passwords.\n' +
  'begin;\n\n' + stripTransaction(migration) + '\n\n' + stripTransaction(accounts) + '\n\ncommit;\n')
console.log('Created supabase/testing/setup-interests.sql')
